parameters.jsonBody:
={{ JSON.stringify({
  model: "gpt-4o-mini",
  messages: [
    {
      role: "system",
      content: "You are a procurement spend classification assistant for an industrial manufacturer. Classify the purchase transaction into exactly one of: raw_materials, mro, packaging, logistics_freight, indirect_facilities, capex_components. Respond ONLY with valid JSON: {\"category\": string, \"confidence\": number (0-1), \"reasoning\": string (one short sentence)}. Base the classification primarily on the line item description, not the vendor name alone -- vendors sometimes supply across multiple categories."
    },
    {
      role: "user",
      content: `Vendor: ${$json.vendor_name}. Description: ${$json.line_item_description}. Amount: $${$json.amount_usd}.`
    }
  ],
  temperature: 0
}) }}

parameters.jsCode:
// Parse the LLM's JSON response and merge it with the original transaction
const llmContent = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(llmContent);
} catch (e) {
  parsed = { category: "unclassified", confidence: 0, reasoning: "LLM response was not valid JSON -- flagged for manual review" };
}

const original = $('Load Sample Transactions').item.json;

return {
  json: {
    ...original,
    ai_category: parsed.category,
    ai_confidence: parsed.confidence,
    ai_reasoning: parsed.reasoning,
    needs_review: parsed.confidence < 0.7
  }
};
